command:
$ErrorActionPreference='Stop'
$env:GIT_TERMINAL_PROMPT='0'
$env:GH_PROMPT_DISABLED='1'
Remove-Item Env:GH_TOKEN -ErrorAction SilentlyContinue
$remote='https://github.com/tngkrwlsmd/universal-agent-docs.git'
$source='b8909a5550168d38e6abbe8df9b504f0759f660c'
$tag='v0.6.3'
$temp=Join-Path $env:TEMP ('uad-release-'+[Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $temp -Force | Out-Null
try {
  & git clone --quiet --depth 1 --branch main $remote $temp
  if($LASTEXITCODE -ne 0){throw 'B clone failed'}
  $head=(& git -C $temp rev-parse HEAD).Trim()
  if($LASTEXITCODE -ne 0 -or $head -ne $source){throw 'B main SHA mismatch'}
  $refs=@(& git -C $temp ls-remote --tags origin "refs/tags/$tag")
  if($LASTEXITCODE -ne 0){throw 'B tag existence check failed'}
  if($refs.Count -ne 0){throw 'B tag already exists, refuse to move it'}
  Write-Output ('B_TAG_PREFLIGHT=PASS SOURCE='+$head)
  & git -C $temp push origin ($source+':refs/tags/'+$tag)
  if($LASTEXITCODE -ne 0){throw 'B_TAG_PUSH=FAILED: check tag state before any retry'}
  $confirm=@(& git -C $temp ls-remote --tags origin "refs/tags/$tag")
  if($LASTEXITCODE -ne 0 -or $confirm.Count -ne 1){throw 'B tag postcondition query failed'}
  $remoteSha=($confirm[0] -split '\s+')[0]
  if($remoteSha -ne $source){throw 'B tag points to unexpected SHA'}
  Write-Output ('B_TAG_PUSH=PASS '+$tag+'@'+$remoteSha)
} finally { Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue }
